package sbe

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"unicode"
)

// generatedHeader is the first line of every generated file, by which a
// regeneration recognises the files it removes.
const generatedHeader = "// Code generated by fix2gen; DO NOT EDIT."

// maxEntries is the default MaxEntries of a generated package.
const maxEntries = 65535

// Generate writes into outDir the Go package pkg holding the codecs of s,
// then removes the files a previous run generated there that it no longer
// emits, and only those.
func Generate(s *Schema, pkg, outDir string) error {
	g := &gen{s: s, pkg: pkg, idents: map[string]string{}, groups: map[string]*Group{}, files: map[string][]byte{}}
	if err := g.generate(); err != nil {
		return fmt.Errorf("sbe: %w", err)
	}
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return err
	}
	for _, name := range slices.Sorted(maps.Keys(g.files)) {
		if err := os.WriteFile(filepath.Join(outDir, name), g.files[name], 0o644); err != nil {
			return err
		}
	}
	return removeStale(outDir, g.files)
}

type gen struct {
	s      *Schema
	pkg    string
	idents map[string]string // package-level Go identifiers, and what declares each
	groups map[string]*Group // the groups whose type is generated, by name
	goName map[*Type]string  // the Go type of each named or inline type
	files  map[string][]byte // generated files, by name
	order  string            // binary.LittleEndian or binary.BigEndian
	w      *bytes.Buffer     // the file being written
	inline map[*Type]*Type   // inline enums, sets and composites, to declare
	decls  []*Type           // types to declare, in order
}

func (g *gen) p(format string, args ...any) {
	fmt.Fprintf(g.w, format, args...)
	g.w.WriteByte('\n')
}

// declare reserves the package-level identifier name for what.
func (g *gen) declare(name, what string) error {
	if prev, ok := g.idents[name]; ok {
		return fmt.Errorf("%s and %s are both %s in Go: rename one", prev, what, name)
	}
	g.idents[name] = what
	return nil
}

// export makes a schema name an exported Go identifier.
func export(name string) string {
	r := []rune(name)
	if !unicode.IsUpper(r[0]) {
		if unicode.IsLetter(r[0]) {
			r[0] = unicode.ToUpper(r[0])
		} else {
			r = append([]rune("X"), r...)
		}
	}
	return string(r)
}

func (g *gen) generate() error {
	g.goName = map[*Type]string{}
	g.order = "binary.LittleEndian"
	if g.s.BigEndian {
		g.order = "binary.BigEndian"
	}
	for _, name := range []string{"SchemaID", "SchemaVersion", "MaxEntries", "HeaderSize", "ReadHeader", "Optional", "Some",
		"ErrShort", "ErrSchema", "ErrTemplate", "ErrMalformed", "ErrLength", "ErrEntries"} {
		g.idents[name] = "fix2gen's " + name
	}
	for _, t := range g.s.Types {
		if err := g.name(t, export(t.Name), fmt.Sprintf("type %q", t.Name)); err != nil {
			return err
		}
	}
	files := map[string]string{}
	for _, m := range g.s.Messages {
		file := "msg_" + snake(m.Name) + ".go"
		if prev, ok := files[file]; ok {
			return fmt.Errorf("messages %q and %q are both written to %s: rename one", prev, m.Name, file)
		}
		files[file] = m.Name
		name := export(m.Name)
		for _, id := range []string{name, name + "TemplateID", name + "BlockLength"} {
			if err := g.declare(id, fmt.Sprintf("message %q", m.Name)); err != nil {
				return err
			}
		}
		if err := g.blockNames(&m.Block, fmt.Sprintf("message %q", m.Name)); err != nil {
			return err
		}
	}

	g.w = &bytes.Buffer{}
	g.common()
	if err := g.flush("sbe.go"); err != nil {
		return err
	}
	g.w = &bytes.Buffer{}
	for _, t := range g.decls {
		g.typeDecl(t)
	}
	if err := g.flush("types.go"); err != nil {
		return err
	}
	for _, m := range g.s.Messages {
		g.w = &bytes.Buffer{}
		g.message(m)
		if err := g.flush("msg_" + snake(m.Name) + ".go"); err != nil {
			return err
		}
	}
	return nil
}

// name gives t, and the inline types of its elements, their Go names.
func (g *gen) name(t *Type, goName, what string) error {
	if t.Kind == KindSimple || t.Kind == KindComposite && hasVarData(t) {
		return nil // a primitive, or the encoding of <data>, not a Go type
	}
	if err := g.declare(goName, what); err != nil {
		return err
	}
	g.goName[t] = goName
	g.decls = append(g.decls, t)
	switch t.Kind {
	case KindEnum, KindSet:
		for _, v := range t.Values {
			if err := g.declare(goName+export(v.Name), fmt.Sprintf("%s value %q", what, v.Name)); err != nil {
				return err
			}
		}
	case KindComposite:
		if err := g.declare(goName+"Size", what); err != nil {
			return err
		}
		members := map[string]string{}
		for _, e := range t.Elements {
			if err := member(members, export(e.Name), fmt.Sprintf("element %q", e.Name)); err != nil {
				return fmt.Errorf("%s: %w", what, err)
			}
			if isString(e.Type) {
				if err := member(members, export(e.Name)+"String", fmt.Sprintf("the String method of %q", e.Name)); err != nil {
					return fmt.Errorf("%s: %w", what, err)
				}
			}
			if e.Ref {
				continue
			}
			if err := g.name(e.Type, goName+export(e.Name), fmt.Sprintf("%s element %q", what, e.Name)); err != nil {
				return err
			}
		}
	}
	return nil
}

// member reserves name among the members of a struct.
func member(members map[string]string, name, what string) error {
	if prev, ok := members[name]; ok {
		return fmt.Errorf("%s and %s are both %s in Go: rename one", prev, what, name)
	}
	members[name] = what
	return nil
}

// blockNames checks the Go names of a message's or group's members, and
// names its groups' types.
func (g *gen) blockNames(b *Block, what string) error {
	members := map[string]string{"AppendTo": "a method", "Decode": "a method", "DecodeBody": "a method"}
	for _, f := range b.Fields {
		if err := member(members, export(f.Name), fmt.Sprintf("field %q", f.Name)); err != nil {
			return fmt.Errorf("%s: %w", what, err)
		}
		if isString(f.Type) && f.Presence != Constant {
			if err := member(members, export(f.Name)+"String", fmt.Sprintf("the String method of %q", f.Name)); err != nil {
				return fmt.Errorf("%s: %w", what, err)
			}
		}
	}
	for _, gr := range b.Groups {
		if err := member(members, export(gr.Name), fmt.Sprintf("group %q", gr.Name)); err != nil {
			return fmt.Errorf("%s: %w", what, err)
		}
		if _, ok := g.groups[gr.Name]; ok {
			continue // the same group, loading checked
		}
		g.groups[gr.Name] = gr
		gw := fmt.Sprintf("group %q", gr.Name)
		name := export(gr.Name)
		for _, id := range []string{name, "decode" + name, "append" + name} {
			if err := g.declare(id, gw); err != nil {
				return err
			}
		}
		if err := g.blockNames(&gr.Block, gw); err != nil {
			return err
		}
	}
	for _, d := range b.Data {
		if err := member(members, export(d.Name), fmt.Sprintf("data %q", d.Name)); err != nil {
			return fmt.Errorf("%s: %w", what, err)
		}
	}
	return nil
}

// isString reports whether t is a char array read as US-ASCII text.
func isString(t *Type) bool {
	if t.Kind != KindSimple || t.Primitive != Char || t.Length < 2 || t.Presence == Constant {
		return false
	}
	switch strings.ToUpper(t.CharacterEncoding) {
	case "", "US-ASCII", "ASCII":
		return true
	}
	return false
}

// flush formats the file being written and keeps it as name.
func (g *gen) flush(name string) error {
	var src bytes.Buffer
	fmt.Fprintf(&src, "%s\n\n", generatedHeader)
	if name == "sbe.go" {
		fmt.Fprintf(&src, "// Package %s holds the codecs of the SBE message schema %s (id %d, version %d),\n// generated by fix2gen sbe.\n", g.pkg, cmp(g.s.Package, "of no package"), g.s.ID, g.s.Version)
	}
	fmt.Fprintf(&src, "package %s\n\n", g.pkg)
	// The packages the code uses, found in its syntax rather than its text,
	// where a schema's description may name one.
	used := map[string]bool{}
	if f, err := parser.ParseFile(token.NewFileSet(), name, src.String()+g.w.String(), parser.SkipObjectResolution); err == nil {
		ast.Inspect(f, func(n ast.Node) bool {
			if sel, ok := n.(*ast.SelectorExpr); ok {
				if id, ok := sel.X.(*ast.Ident); ok {
					used[id.Name] = true
				}
			}
			return true
		})
	}
	var imports []string
	for _, imp := range []string{"bytes", "encoding/binary", "errors", "fmt", "math", "slices"} {
		if used[imp[strings.LastIndexByte(imp, '/')+1:]] {
			imports = append(imports, strconv.Quote(imp))
		}
	}
	if len(imports) > 0 {
		fmt.Fprintf(&src, "import (\n%s\n)\n\n", strings.Join(imports, "\n"))
	}
	src.WriteString(g.w.String())
	out, err := format.Source(src.Bytes())
	if err != nil {
		return fmt.Errorf("%s: generated code does not format: %w\n%s", name, err, src.String())
	}
	g.files[name] = out
	return nil
}

func cmp(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

// comment writes the doc comment of a declaration.
func (g *gen) comment(name, what, description string) {
	text := name + " is " + what
	if d := strings.Join(strings.Fields(description), " "); d != "" {
		text += ": " + d
	}
	text += "."
	for _, line := range wrap(text, 76) {
		g.p("// %s", line)
	}
}

func wrap(text string, width int) []string {
	var lines []string
	line := ""
	for _, word := range strings.Fields(text) {
		if line != "" && len(line)+1+len(word) > width {
			lines = append(lines, line)
			line = ""
		}
		if line != "" {
			line += " "
		}
		line += word
	}
	return append(lines, line)
}

// common writes what every generated package holds: the schema's
// identity, errors, Optional, the header and the primitive accessors.
func (g *gen) common() {
	h := g.s.Header
	hname := g.goName[h]
	g.p(`const (
	// SchemaID is the schema's id, which every message header carries.
	SchemaID = %d
	// SchemaVersion is the schema's version, which every message header carries.
	SchemaVersion = %d
	// MaxEntries bounds the group entries a message may hold, across its
	// groups and theirs: what decoding allocates is bounded by it, however
	// small the entries are on the wire.
	MaxEntries = %d
	// HeaderSize is the length of the message header.
	HeaderSize = %sSize
)`, g.s.ID, g.s.Version, maxEntries, hname)
	g.p(`
var (
	// ErrShort reports a message shorter than its layout.
	ErrShort = errors.New("%[1]s: message shorter than its layout")
	// ErrSchema reports a message of another schema.
	ErrSchema = errors.New("%[1]s: message of another schema")
	// ErrTemplate reports a message of another template.
	ErrTemplate = errors.New("%[1]s: message of another template")
	// ErrMalformed reports a message whose structure is not the schema's.
	ErrMalformed = errors.New("%[1]s: malformed message")
	// ErrLength reports data shorter or longer than its length allows.
	ErrLength = errors.New("%[1]s: data length out of bounds")
	// ErrEntries reports a group entry count out of its bounds, or beyond MaxEntries.
	ErrEntries = errors.New("%[1]s: group entry count out of bounds")
)

// Optional is a value that may be null on the wire. The zero Optional is
// null.
type Optional[T any] struct {
	Value T
	Valid bool
}

// Some returns v, not null.
func Some[T any](v T) Optional[T] { return Optional[T]{Value: v, Valid: true} }

// ReadHeader decodes the message header at the start of b, and returns the
// message body after it.
func ReadHeader(b []byte) (%[2]s, []byte, error) {
	var h %[2]s
	if len(b) < HeaderSize {
		return h, nil, ErrShort
	}
	h.decodeFrom(b[:HeaderSize], math.MaxInt)
	return h, b[HeaderSize:], nil
}

// extend appends n zero bytes to b, and returns b and those bytes.
func extend(b []byte, n int) ([]byte, []byte) {
	l := len(b)
	b = slices.Grow(b, n)[:l+n]
	clear(b[l:])
	return b, b[l:]
}

// cstring returns the text of a char array, up to its first NUL.
func cstring(b []byte) string {
	if i := bytes.IndexByte(b, 0); i >= 0 {
		b = b[:i]
	}
	return string(b)
}`, g.pkg, hname)
	o := g.order
	g.p(`
func getChar(b []byte) byte { return b[0] }
func putChar(b []byte, v byte) { b[0] = v }
func getUint8(b []byte) uint8 { return b[0] }
func putUint8(b []byte, v uint8) { b[0] = v }
func getInt8(b []byte) int8 { return int8(b[0]) }
func putInt8(b []byte, v int8) { b[0] = byte(v) }
func getUint16(b []byte) uint16 { return %[1]s.Uint16(b) }
func putUint16(b []byte, v uint16) { %[1]s.PutUint16(b, v) }
func getInt16(b []byte) int16 { return int16(%[1]s.Uint16(b)) }
func putInt16(b []byte, v int16) { %[1]s.PutUint16(b, uint16(v)) }
func getUint32(b []byte) uint32 { return %[1]s.Uint32(b) }
func putUint32(b []byte, v uint32) { %[1]s.PutUint32(b, v) }
func getInt32(b []byte) int32 { return int32(%[1]s.Uint32(b)) }
func putInt32(b []byte, v int32) { %[1]s.PutUint32(b, uint32(v)) }
func getUint64(b []byte) uint64 { return %[1]s.Uint64(b) }
func putUint64(b []byte, v uint64) { %[1]s.PutUint64(b, v) }
func getInt64(b []byte) int64 { return int64(%[1]s.Uint64(b)) }
func putInt64(b []byte, v int64) { %[1]s.PutUint64(b, uint64(v)) }
func getFloat(b []byte) float32 { return math.Float32frombits(%[1]s.Uint32(b)) }
func putFloat(b []byte, v float32) { %[1]s.PutUint32(b, math.Float32bits(v)) }
func getDouble(b []byte) float64 { return math.Float64frombits(%[1]s.Uint64(b)) }
func putDouble(b []byte, v float64) { %[1]s.PutUint64(b, math.Float64bits(v)) }`, o)
}

// accessor is the suffix of the get and put functions of p.
func accessor(p Primitive) string {
	return map[Primitive]string{Char: "Char", Int8: "Int8", Int16: "Int16", Int32: "Int32", Int64: "Int64",
		Uint8: "Uint8", Uint16: "Uint16", Uint32: "Uint32", Uint64: "Uint64", Float: "Float", Double: "Double"}[p]
}

// goPrim is the Go type of p.
func goPrim(p Primitive) string {
	return map[Primitive]string{Char: "byte", Int8: "int8", Int16: "int16", Int32: "int32", Int64: "int64",
		Uint8: "uint8", Uint16: "uint16", Uint32: "uint32", Uint64: "uint64", Float: "float32", Double: "float64"}[p]
}

// goType is the Go type of a value of t, Optional aside.
func (g *gen) goType(t *Type) string {
	if t.Kind != KindSimple {
		return g.goName[t]
	}
	if t.Length == 1 {
		return goPrim(t.Primitive)
	}
	return fmt.Sprintf("[%d]%s", t.Length, goPrim(t.Primitive))
}

// optional reports whether a member of type t and presence p is an
// Optional: an optional scalar or enum. A composite is optional through its
// first element, an array or a set not at all.
func optional(t *Type, p Presence) bool {
	return p == Optional && (t.Scalar() || t.Kind == KindEnum)
}

// nullOf returns the null value of an optional member of type t, as Go
// source of t's primitive, and that primitive.
func nullOf(t *Type) (string, Primitive) {
	if t.Kind == KindEnum {
		if t.Encoding.Null != "" {
			return t.Encoding.Null, t.Encoding.Primitive
		}
		return t.Encoding.Primitive.defaultNull(), t.Encoding.Primitive
	}
	if t.Null != "" {
		return t.Null, t.Primitive
	}
	// A required type used by an optional field: its primitive's null.
	return t.Primitive.defaultNull(), t.Primitive
}

// zero returns the zero value of a member of type t and presence p.
func (g *gen) zero(t *Type, p Presence) string {
	switch {
	case optional(t, p):
		return "Optional[" + g.goType(t) + "]{}"
	case t.Kind == KindComposite, t.Kind == KindSimple && t.Length > 1:
		return g.goType(t) + "{}"
	}
	return "0"
}

// getMember writes the decoding of a member of type t and presence p, at
// offset off of buf, into dst.
func (g *gen) getMember(dst, buf string, off int, t *Type, p Presence) {
	at := fmt.Sprintf("%s[%d:]", buf, off)
	switch {
	case t.Kind == KindComposite:
		g.p("%s.decodeFrom(%s[%d:%d], version)", dst, buf, off, off+t.Size)
	case t.Kind == KindSimple && t.Length > 1:
		if t.Primitive == Char || t.Primitive == Uint8 {
			g.p("copy(%s[:], %s[%d:%d])", dst, buf, off, off+t.Size)
		} else {
			g.p("for i := range %s {", dst)
			g.p("%s[i] = get%s(%s[%d+i*%d:])", dst, accessor(t.Primitive), buf, off, t.Primitive.Size())
			g.p("}")
		}
	case optional(t, p):
		null, prim := nullOf(t)
		get := fmt.Sprintf("get%s(%s)", accessor(prim), at)
		cond := "v != " + null
		if prim == Float || prim == Double {
			if null == "NaN" {
				cond = "v == v"
			}
		}
		if t.Kind == KindEnum {
			get = fmt.Sprintf("%s(%s)", g.goName[t], get)
			cond = fmt.Sprintf("v != %s(%s)", g.goName[t], null)
		}
		g.p("if v := %s; %s {", get, cond)
		g.p("%s = Optional[%s]{Value: v, Valid: true}", dst, g.goType(t))
		g.p("} else {")
		g.p("%s = Optional[%s]{}", dst, g.goType(t))
		g.p("}")
	case t.Kind == KindEnum || t.Kind == KindSet:
		g.p("%s = %s(get%s(%s))", dst, g.goName[t], accessor(t.Encoding.Primitive), at)
	default:
		g.p("%s = get%s(%s)", dst, accessor(t.Primitive), at)
	}
}

// putMember writes the encoding of a member src of type t and presence p,
// at offset off of buf.
func (g *gen) putMember(src, buf string, off int, t *Type, p Presence) {
	at := fmt.Sprintf("%s[%d:]", buf, off)
	switch {
	case t.Kind == KindComposite:
		g.p("%s.putTo(%s[%d:%d])", src, buf, off, off+t.Size)
	case t.Kind == KindSimple && t.Length > 1:
		if t.Primitive == Char || t.Primitive == Uint8 {
			g.p("copy(%s[%d:%d], %s[:])", buf, off, off+t.Size, src)
		} else {
			g.p("for i, v := range %s {", src)
			g.p("put%s(%s[%d+i*%d:], v)", accessor(t.Primitive), buf, off, t.Primitive.Size())
			g.p("}")
		}
	case optional(t, p):
		null, prim := nullOf(t)
		value := src + ".Value"
		if t.Kind == KindEnum {
			value = fmt.Sprintf("%s(%s)", goPrim(prim), value)
		}
		nullExpr := null
		if null == "NaN" {
			nullExpr = map[Primitive]string{Float: "float32(math.NaN())", Double: "math.NaN()"}[prim]
		}
		g.p("if %s.Valid {", src)
		g.p("put%s(%s, %s)", accessor(prim), at, value)
		g.p("} else {")
		g.p("put%s(%s, %s)", accessor(prim), at, nullExpr)
		g.p("}")
	case t.Kind == KindEnum || t.Kind == KindSet:
		g.p("put%s(%s, %s(%s))", accessor(t.Encoding.Primitive), at, goPrim(t.Encoding.Primitive), src)
	default:
		g.p("put%s(%s, %s)", accessor(t.Primitive), at, src)
	}
}

// constant returns the Go type and value of a constant member of type t,
// valueRef ref ("" if none).
func (g *gen) constant(t *Type, ref string) (string, string) {
	if ref == "" {
		ref = t.ValueRef
	}
	if ref != "" {
		enumName, valueName, _ := strings.Cut(ref, ".")
		for _, et := range g.s.Types {
			if et.Name == enumName {
				return g.goName[et], g.goName[et] + export(valueName)
			}
		}
	}
	if t.Primitive == Char && t.Length > 1 {
		return "string", strconv.Quote(t.Constant)
	}
	v, _ := t.Primitive.parseValue(t.Constant)
	if t.Primitive == Char {
		return "byte", charLiteral(v)
	}
	if v == "NaN" {
		return goPrim(t.Primitive), map[Primitive]string{Float: "float32(math.NaN())", Double: "math.NaN()"}[t.Primitive]
	}
	return goPrim(t.Primitive), v
}

// charLiteral returns a char value, given as its code, as a Go literal.
func charLiteral(code string) string {
	n, _ := strconv.Atoi(code)
	if n >= 0x20 && n < 0x7f && n != '\'' && n != '\\' {
		return "'" + string(rune(n)) + "'"
	}
	return code
}

// typeDecl declares an enum, a set or a composite.
func (g *gen) typeDecl(t *Type) {
	name := g.goName[t]
	g.p("")
	switch t.Kind {
	case KindEnum:
		g.comment(name, "the enum "+t.Name, t.Description)
		g.p("type %s %s", name, goPrim(t.Encoding.Primitive))
		g.p("\n// The values of %s.\nconst (", name)
		for _, v := range t.Values {
			if v.Description != "" {
				g.p("// %s", strings.Join(strings.Fields(v.Description), " "))
			}
			lit := v.Value
			if t.Encoding.Primitive == Char {
				lit = charLiteral(v.Value)
			}
			g.p("%s%s %s = %s", name, export(v.Name), name, lit)
		}
		g.p(")")
		g.p("\n// Known reports whether e is a value the schema lists.\nfunc (e %s) Known() bool {\nswitch e {", name)
		var cases []string
		for _, v := range t.Values {
			cases = append(cases, name+export(v.Name))
		}
		g.p("case %s:\nreturn true\n}\nreturn false\n}", strings.Join(cases, ", "))
		g.p("\nfunc (e %s) String() string {\nswitch e {", name)
		for _, v := range t.Values {
			g.p("case %s%s:\nreturn %q", name, export(v.Name), v.Name)
		}
		g.p("}\nreturn fmt.Sprintf(\"%s(%%d)\", %s(e))\n}", name, goPrim(t.Encoding.Primitive))
	case KindSet:
		g.comment(name, "the set "+t.Name+", each of its choices a bit", t.Description)
		g.p("type %s %s", name, goPrim(t.Encoding.Primitive))
		if len(t.Values) > 0 {
			g.p("\n// The choices of %s.\nconst (", name)
			for _, v := range t.Values {
				g.p("%s%s %s = 1 << %s", name, export(v.Name), name, v.Value)
			}
			g.p(")")
		}
	case KindComposite:
		g.comment(name, "the composite "+t.Name, t.Description)
		g.p("type %s struct {", name)
		for _, e := range t.Elements {
			if e.Type.Presence == Constant {
				continue
			}
			typ := g.goType(e.Type)
			if optional(e.Type, e.Type.Presence) {
				typ = "Optional[" + typ + "]"
			}
			if e.Type.Description != "" {
				g.p("// %s", strings.Join(strings.Fields(e.Type.Description), " "))
			}
			g.p("%s %s", export(e.Name), typ)
		}
		g.p("}")
		g.p("\n// %sSize is the length of %s on the wire.\nconst %sSize = %d", name, name, name, t.Size)
		for _, e := range t.Elements {
			if e.Type.Presence != Constant {
				if isString(e.Type) {
					g.p("\n// %sString returns %s as text, up to its first NUL.\nfunc (c *%s) %sString() string { return cstring(c.%s[:]) }",
						export(e.Name), export(e.Name), name, export(e.Name), export(e.Name))
				}
				continue
			}
			typ, val := g.constant(e.Type, "")
			g.p("\n// %s is the constant %s.\nfunc (*%s) %s() %s { return %s }", export(e.Name), e.Name, name, export(e.Name), typ, val)
		}
		g.p("\nfunc (c *%s) decodeFrom(b []byte, version int) {", name)
		if t.Size > 0 {
			g.p("_ = b[%d]", t.Size-1)
		}
		g.p("_ = version")
		for _, e := range t.Elements {
			if e.Type.Presence == Constant {
				continue
			}
			dst := "c." + export(e.Name)
			if e.Type.SinceVersion > 0 {
				g.p("if version >= %d {", e.Type.SinceVersion)
			}
			g.getMember(dst, "b", e.Offset, e.Type, e.Type.Presence)
			if e.Type.SinceVersion > 0 {
				g.p("} else {\n%s = %s\n}", dst, g.zero(e.Type, e.Type.Presence))
			}
		}
		g.p("}")
		g.p("\nfunc (c *%s) putTo(b []byte) {", name)
		if t.Size > 0 {
			g.p("_ = b[%d]", t.Size-1)
		}
		for _, e := range t.Elements {
			if e.Type.Presence == Constant {
				continue
			}
			g.putMember("c."+export(e.Name), "b", e.Offset, e.Type, e.Type.Presence)
		}
		g.p("}")
	}
}

// message writes a message's constants, struct and codec.
func (g *gen) message(m *Message) {
	name := export(m.Name)
	h := g.s.Header
	g.p("// %sTemplateID is the template id of %s.\nconst %sTemplateID = %d", name, name, name, m.ID)
	g.p("\n// %sBlockLength is the length of the root block of %s.\nconst %sBlockLength = %d", name, name, name, m.BlockLength)
	g.p("")
	g.comment(name, "the message "+m.Name, m.Description)
	g.block(name, &m.Block)

	hv := func(elem, value string) {
		if element(h, elem) != nil {
			g.p("%s: %s,", export(elem), value)
		}
	}
	g.p("\n// AppendTo appends m to dst, its header included. It fails without\n// appending if a data field or a group does not fit its encoding.")
	g.p("func (m *%s) AppendTo(dst []byte) ([]byte, error) {", name)
	g.p("if err := m.check(); err != nil {\nreturn dst, err\n}")
	g.p("h := %s{", g.goName[h])
	hv("blockLength", strconv.Itoa(m.BlockLength))
	hv("templateId", strconv.FormatUint(m.ID, 10))
	hv("schemaId", "SchemaID")
	hv("version", "SchemaVersion")
	hv("numGroups", strconv.Itoa(len(m.Groups)))
	hv("numVarDataFields", strconv.Itoa(len(m.Data)))
	g.p("}")
	g.p("dst, b := extend(dst, HeaderSize+%d)", m.BlockLength)
	g.p("h.putTo(b[:HeaderSize])\nm.putBlock(b[HeaderSize:])\nreturn m.appendRest(dst), nil\n}")

	g.p("\n// Decode decodes m from b, a message with its header. Its []byte fields\n// alias b. On error, m is left zero.")
	g.p("func (m *%s) Decode(b []byte) error {", name)
	g.p("h, body, err := ReadHeader(b)")
	g.p("if err == nil && uint64(h.%s) != SchemaID {\nerr = ErrSchema\n}", export("schemaId"))
	g.p("if err != nil {\n*m = %s{}\nreturn err\n}\nreturn m.DecodeBody(h, body)\n}", name)

	g.p("\n// DecodeBody decodes m from body, the message body after header h. Its\n// []byte fields alias body. On error, m is left zero.")
	g.p("func (m *%s) DecodeBody(h %s, body []byte) error {", name, g.goName[h])
	g.p("if uint64(h.%s) != %sTemplateID {\n*m = %s{}\nreturn ErrTemplate\n}", export("templateId"), name, name)
	g.p("// Bounded before they become ints, which a wide one would wrap.")
	g.p("if uint64(h.%s) > uint64(len(body)) {\n*m = %s{}\nreturn ErrShort\n}", export("blockLength"), name)
	g.p("version := int(min(uint64(h.%s), 1<<31-1))", export("version"))
	g.p("entries := 0")
	g.p("if _, err := m.decode(body, int(h.%s), version, &entries); err != nil {\n*m = %s{}\nreturn err\n}\nreturn nil\n}",
		export("blockLength"), name)

	for _, gr := range m.Groups {
		g.group(gr)
	}
}

// group writes the type and codec of a group, and of its own groups, unless
// already written.
func (g *gen) group(gr *Group) {
	if g.groups[gr.Name] == nil {
		return
	}
	delete(g.groups, gr.Name) // written once
	name := export(gr.Name)
	dim := gr.Dimension
	dname := g.goName[dim]
	g.p("")
	g.comment(name, "an entry of the group "+gr.Name, gr.Description)
	g.block(name, &gr.Block)

	g.p("\nfunc decode%s(s *[]%s, b []byte, version int, entries *int) (int, error) {", name, name)
	g.p("if len(b) < %sSize {\nreturn 0, ErrShort\n}", dname)
	g.p("var d %s\nd.decodeFrom(b[:%sSize], version)", dname, dname)
	g.p("count := uint64(d.%s)", export("numInGroup"))
	var bounds []string
	if gr.MinEntries > 0 {
		bounds = append(bounds, fmt.Sprintf("count < %d", gr.MinEntries))
	}
	if gr.MaxEntriesSet {
		bounds = append(bounds, fmt.Sprintf("count > %d", gr.MaxEntries))
	}
	if len(bounds) > 0 {
		g.p("if %s {\nreturn 0, ErrEntries\n}", strings.Join(bounds, " || "))
	}
	g.p("pos := %sSize", dname)
	g.p("if count == 0 {\n*s = (*s)[:0]\nreturn pos, nil\n}")
	g.p("// The block length and the count are bounded by the bytes left before\n// they become ints, which a wide one would wrap.")
	g.p("if uint64(d.%s) > uint64(len(b)-pos) {\nreturn 0, ErrShort\n}", export("blockLength"))
	g.p("blockLen := int(d.%s)", export("blockLength"))
	g.p("// An entry takes at least its block, its groups' dimensions and its\n// data's lengths: what the bytes left allow bounds the count.")
	g.p("minEntry := blockLen")
	for _, sub := range gr.Groups {
		g.since(sub.SinceVersion, fmt.Sprintf("minEntry += %sSize", g.goName[sub.Dimension]))
	}
	for _, d := range gr.Data {
		g.since(d.SinceVersion, fmt.Sprintf("minEntry += %d", d.Type.Elements[0].Type.Size))
	}
	g.p("if minEntry == 0 {\nreturn 0, ErrMalformed\n}")
	g.p("if count > uint64((len(b)-pos)/minEntry) {\nreturn 0, ErrShort\n}")
	g.p("n := int(count)")
	g.p("if *entries += n; *entries > MaxEntries {\nreturn 0, ErrEntries\n}")
	g.p("if cap(*s) < n {\n*s = make([]%s, n)\n} else {\n*s = (*s)[:n]\n}", name)
	g.p("for i := range *s {")
	g.p("c, err := (*s)[i].decode(b[pos:], blockLen, version, entries)")
	g.p("if err != nil {\nreturn 0, err\n}\npos += c\n}\nreturn pos, nil\n}")

	g.p("\nfunc append%s(dst []byte, s []%s) []byte {", name, name)
	g.p("var d %s", dname)
	g.p("d.%s = %d", export("blockLength"), gr.BlockLength)
	g.p("d.%s = %s(len(s))", export("numInGroup"), goPrim(element(dim, "numInGroup").Type.Primitive))
	if e := element(dim, "numGroups"); e != nil {
		g.p("d.NumGroups = %d", len(gr.Groups))
	}
	if e := element(dim, "numVarDataFields"); e != nil {
		g.p("d.NumVarDataFields = %d", len(gr.Data))
	}
	g.p("dst, b := extend(dst, %sSize)\nd.putTo(b)", dname)
	g.p("for i := range s {\ndst, b = extend(dst, %d)\ns[i].putBlock(b)\ndst = s[i].appendRest(dst)\n}\nreturn dst\n}", gr.BlockLength)

	for _, sub := range gr.Groups {
		g.group(sub)
	}
}

// since writes stmt, run only from version v on.
func (g *gen) since(v int, stmt string) {
	if v == 0 {
		g.p("%s", stmt)
		return
	}
	g.p("if version >= %d {\n%s\n}", v, stmt)
}

// block writes the struct of a message or group entry, and its block
// codec: decode, check, putBlock and appendRest.
func (g *gen) block(name string, b *Block) {
	g.p("type %s struct {", name)
	for _, f := range b.Fields {
		if f.Presence == Constant {
			continue
		}
		typ := g.goType(f.Type)
		if optional(f.Type, f.Presence) {
			typ = "Optional[" + typ + "]"
		}
		g.fieldComment(f.Description, f.ID, f.SinceVersion)
		g.p("%s %s", export(f.Name), typ)
	}
	for _, gr := range b.Groups {
		g.fieldComment(gr.Description, gr.ID, gr.SinceVersion)
		g.p("%s []%s", export(gr.Name), export(gr.Name))
	}
	for _, d := range b.Data {
		g.fieldComment(d.Description, d.ID, d.SinceVersion)
		g.p("%s []byte", export(d.Name))
	}
	g.p("}")

	for _, f := range b.Fields {
		fname := export(f.Name)
		if f.Presence == Constant {
			typ, val := g.constant(f.Type, f.ValueRef)
			g.p("\n// %s is the constant %s.\nfunc (*%s) %s() %s { return %s }", fname, f.Name, name, fname, typ, val)
		} else if isString(f.Type) {
			g.p("\n// %sString returns %s as text, up to its first NUL.\nfunc (m *%s) %sString() string { return cstring(m.%s[:]) }",
				fname, fname, name, fname, fname)
		}
	}

	// decode
	g.p("\n// decode decodes m from b: a block of blockLen bytes, then groups and\n// data. It returns the bytes it read.")
	g.p("func (m *%s) decode(b []byte, blockLen, version int, entries *int) (int, error) {", name)
	g.p("if len(b) < blockLen {\nreturn 0, ErrShort\n}")
	g.p("_ = entries")
	// The fields of the first version must all be in the block; a later
	// version's, if the message is of that version or later.
	end := 0
	for _, f := range b.Fields {
		if f.Presence != Constant && f.SinceVersion == 0 {
			end = max(end, f.Offset+f.Type.Size)
		}
	}
	if end > 0 {
		g.p("if blockLen < %d {\nreturn 0, ErrMalformed\n}", end)
	}
	for _, f := range b.Fields {
		if f.Presence == Constant {
			continue
		}
		dst := "m." + export(f.Name)
		if f.SinceVersion > 0 {
			g.p("if version >= %d {", f.SinceVersion)
			g.p("if blockLen < %d {\nreturn 0, ErrMalformed\n}", f.Offset+f.Type.Size)
		}
		g.getMember(dst, "b", f.Offset, f.Type, f.Presence)
		if f.SinceVersion > 0 {
			g.p("} else {\n%s = %s\n}", dst, g.zero(f.Type, f.Presence))
		}
	}
	g.p("pos := blockLen")
	for _, gr := range b.Groups {
		gname := export(gr.Name)
		if gr.SinceVersion > 0 {
			g.p("if version >= %d {", gr.SinceVersion)
		}
		g.p("{\nn, err := decode%s(&m.%s, b[pos:], version, entries)\nif err != nil {\nreturn 0, err\n}\npos += n\n}", gname, gname)
		if gr.SinceVersion > 0 {
			g.p("} else {\nm.%s = m.%s[:0]\n}", gname, gname)
		}
	}
	for _, d := range b.Data {
		dname := export(d.Name)
		length := d.Type.Elements[0].Type
		if d.SinceVersion > 0 {
			g.p("if version >= %d {", d.SinceVersion)
		}
		g.p("{\nif len(b)-pos < %d {\nreturn 0, ErrShort\n}", length.Size)
		g.p("l := uint64(get%s(b[pos:]))\npos += %d", accessor(length.Primitive), length.Size)
		g.p("if %s {\nreturn 0, ErrMalformed\n}", lengthBounds("l", d))
		g.p("if uint64(len(b)-pos) < l {\nreturn 0, ErrShort\n}")
		g.p("m.%s = b[pos : pos+int(l) : pos+int(l)]\npos += int(l)\n}", dname)
		if d.SinceVersion > 0 {
			g.p("} else {\nm.%s = nil\n}", dname)
		}
	}
	g.p("return pos, nil\n}")

	// check
	g.p("\n// check reports whether m's groups and data fit their encodings.")
	g.p("func (m *%s) check() error {", name)
	for _, gr := range b.Groups {
		gname := export(gr.Name)
		bounds := fmt.Sprintf("uint64(len(m.%s)) > %d", gname, gr.MaxEntries)
		if gr.MinEntries > 0 {
			bounds = fmt.Sprintf("uint64(len(m.%s)) < %d || %s", gname, gr.MinEntries, bounds)
		}
		g.p("if %s {\nreturn ErrEntries\n}", bounds)
		g.p("for i := range m.%s {\nif err := m.%s[i].check(); err != nil {\nreturn err\n}\n}", gname, gname)
	}
	for _, d := range b.Data {
		g.p("if %s {\nreturn ErrLength\n}", lengthBounds(fmt.Sprintf("uint64(len(m.%s))", export(d.Name)), d))
	}
	g.p("return nil\n}")

	// putBlock
	g.p("\n// putBlock encodes m's fields into b, its zeroed block.")
	g.p("func (m *%s) putBlock(b []byte) {", name)
	if b.BlockLength > 0 {
		g.p("_ = b[%d]", b.BlockLength-1)
	}
	for _, f := range b.Fields {
		if f.Presence == Constant {
			continue
		}
		g.putMember("m."+export(f.Name), "b", f.Offset, f.Type, f.Presence)
	}
	g.p("}")

	// appendRest
	g.p("\n// appendRest appends m's groups and data to dst.")
	g.p("func (m *%s) appendRest(dst []byte) []byte {", name)
	for _, gr := range b.Groups {
		g.p("dst = append%s(dst, m.%s)", export(gr.Name), export(gr.Name))
	}
	for _, d := range b.Data {
		length := d.Type.Elements[0].Type
		g.p("{\nvar l [%d]byte\nput%s(l[:], %s(len(m.%s)))\ndst = append(dst, l[:]...)\n}", length.Size, accessor(length.Primitive), goPrim(length.Primitive), export(d.Name))
		g.p("dst = append(dst, m.%s...)", export(d.Name))
	}
	g.p("return dst\n}")
}

// lengthBounds returns the condition of a length l of data d out of its
// bounds.
func lengthBounds(l string, d *Data) string {
	cond := fmt.Sprintf("%s > %d", l, d.MaxLength)
	if d.MinLength > 0 {
		cond = fmt.Sprintf("%s < %d || %s", l, d.MinLength, cond)
	}
	return cond
}

func (g *gen) fieldComment(description string, id uint64, since int) {
	text := strings.Join(strings.Fields(description), " ")
	if text != "" {
		text += " "
	}
	text += fmt.Sprintf("(id %d", id)
	if since > 0 {
		text += fmt.Sprintf(", since version %d", since)
	}
	text += ")"
	for _, line := range wrap(text, 72) {
		g.p("// %s", line)
	}
}

var snakeRE = regexp.MustCompile(`([a-z0-9])([A-Z])`)

// snake turns a name into a file name.
func snake(name string) string {
	return strings.ToLower(snakeRE.ReplaceAllString(name, "${1}_${2}"))
}

// removeStale deletes the .go files of outDir that start with
// generatedHeader but were not generated now.
func removeStale(outDir string, written map[string][]byte) error {
	entries, err := os.ReadDir(outDir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		name := e.Name()
		if !e.Type().IsRegular() || filepath.Ext(name) != ".go" || written[name] != nil {
			continue
		}
		path := filepath.Join(outDir, name)
		f, err := os.Open(path)
		if err != nil {
			return err
		}
		head := make([]byte, len(generatedHeader))
		_, err = io.ReadFull(f, head)
		f.Close()
		if err != nil && !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
			return err
		}
		if string(head) == generatedHeader {
			if err := os.Remove(path); err != nil {
				return err
			}
		}
	}
	return nil
}
